.shop-page{color:#ffffff}.shop-page .sec-title{padding:38px 20px 30px;margin:0 auto 22px;border-radius:4px;background:linear-gradient(135deg,#ff2d5522,#f5c51822);border:1px solid rgba(255,45,85,.4);text-align:center}
.shop-page .sec-title h1{color:#ffffff}.shop-page .sec-title p{color:#c9a9b5}.shop-page .sec-title .kicker{color:#ff2d55;font-weight:800}
